# hypothesis: a bool argument matches none of the Literal[True] or Literal[False] overloads directly, so overload resolution must fall back to the bool overload and return str | int.
from typing import Literal, assert_type, overload, reveal_type


@overload
def parse(x: Literal[True]) -> str: ...


@overload
def parse(x: Literal[False]) -> int: ...


@overload
def parse(x: bool) -> str | int: ...


def parse(x: bool) -> str | int:
    return 'yes' if x else 0


def from_flag(flag: bool) -> str | int:
    result = parse(flag)
    reveal_type(result)
    return result


def from_literal(b: Literal[True]) -> str:
    assert_type(parse(b), str)
    return parse(b)


assert_type(parse(True), str)
assert_type(parse(False), int)
assert from_flag(True) == 'yes'
assert from_flag(False) == 0
assert from_literal(True) == 'yes'
